let _markdown = "\n\nOverview [#overview]\n\n<FeedbackBlock id=\"7e0d91d2b108040f\" body=\"Feedback is crucial for knowing what your reader thinks, and help you to further improve documentation content.\">\n  Feedback is crucial for knowing what your reader thinks, and help you to further improve documentation content.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"24cffc78742b63f7\" body=\"You can integrate a simple feedback system with Fumadocs.\">\n  You can integrate a simple feedback system with Fumadocs.\n</FeedbackBlock>\n\nInstallation [#installation]\n\n<FeedbackBlock id=\"c305541fdd26fae2\" body=\"Install it using Fumadocs CLI.\">\n  Install it using **Fumadocs CLI**.\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"npm\" groupId=\"package-manager\" persist>\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"npm\">\n      npm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"pnpm\">\n      pnpm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"yarn\">\n      yarn\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"bun\">\n      bun\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"npm\">\n    ```bash\n    npx @fumadocs/cli@latest add feedback\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"pnpm\">\n    ```bash\n    pnpm dlx @fumadocs/cli@latest add feedback\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"yarn\">\n    ```bash\n    yarn dlx @fumadocs/cli@latest add feedback\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"bun\">\n    ```bash\n    bun x @fumadocs/cli@latest add feedback\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\nPage Feedback [#page-feedback]\n\n<FeedbackBlock id=\"08b42448939164e6\" body=\"To create a page-level feedback UI, add the <Feedback /> component to your docs page:\">\n  To create a page-level feedback UI, add the `<Feedback />` component to your docs page:\n</FeedbackBlock>\n\n```tsx\nimport { DocsPage } from 'fumadocs-ui/layout/docs/page';\nimport { Feedback } from '@/components/feedback/client';\nimport posthog from 'posthog-js';\n\nexport default async function Page() {\n  return (\n    <DocsPage>\n      <Feedback\n        onSendAction={async (feedback) => {\n          'use server';\n\n          await posthog.capture('on_rate_docs', feedback);\n        }}\n      />\n    </DocsPage>\n  );\n}\n```\n\n<FeedbackBlock id=\"ad2693c986909f81\" body=\"onSendAction: fired when user submit feedback.\">\n  * `onSendAction`: fired when user submit feedback.\n</FeedbackBlock>\n\n<FeedbackBlock\n  id=\"b7387d59ae885e7e\"\n  body=\"You can specify a server action, or any function (in client component) to handle the user feedback.\nFor example, to report user feedback as a on_rate_docs event on PostHog.\"\n>\n  You can specify a server action, or any function (in client component) to handle the user feedback.\n  For example, to report user feedback as a `on_rate_docs` event on PostHog.\n</FeedbackBlock>\n\nFeedback Block [#feedback-block]\n\n<FeedbackBlock id=\"8fad89d29d0252c6\" body=\"You can also configure block-level feedback (e.g. a feedback popover for each paragraph).\">\n  You can also configure block-level feedback (e.g. a feedback popover for each paragraph).\n</FeedbackBlock>\n\n<FeedbackBlock id=\"f9bbe935ed7485b4\" body=\"Add the remark-feedback-block Remark plugin:\">\n  Add the `remark-feedback-block` Remark plugin:\n</FeedbackBlock>\n\n```tsx title=\"source.config.ts (Fumadocs MDX)\"\nimport { remarkFeedbackBlock } from 'fumadocs-core/mdx-plugins/remark-feedback-block';\nimport { defineConfig } from 'fumadocs-mdx/config';\n\nexport default defineConfig({\n  mdxOptions: {\n    // [!code ++]\n    remarkPlugins: [remarkFeedbackBlock],\n  },\n});\n```\n\n<FeedbackBlock id=\"f5c13741af58637c\" body=\"Then, define the FeedbackBlock MDX component:\">\n  Then, define the `FeedbackBlock` MDX component:\n</FeedbackBlock>\n\n```tsx title=\"mdx-components.tsx\"\nimport { FeedbackBlock } from '@/components/feedback/client';\nimport defaultComponents from 'fumadocs-ui/mdx';\nimport type { MDXComponents } from 'mdx/types';\n\nexport function getMDXComponents(components?: MDXComponents): MDXComponents {\n  return {\n    ...defaultComponents,\n    FeedbackBlock: (props) => (\n      <FeedbackBlock {...props} onSendAction={onBlockFeedbackAction}>\n        {children}\n      </FeedbackBlock>\n    ),\n    ...components,\n  };\n}\n```\n\n<FeedbackBlock id=\"ad2693c986909f81-1\" body=\"onSendAction: fired when user submit feedback.\">\n  * `onSendAction`: fired when user submit feedback.\n</FeedbackBlock>\n\n<Callout type=\"info\" title=\"Good to know\">\n  `remark-feedback-block` generates a block ID from its content and order in the page, hence it is also possible to track the blocks from 3rd party services.\n</Callout>\n\nIntegrating with GitHub Discussion [#integrating-with-github-discussion]\n\n<FeedbackBlock id=\"884ca05ff45de859\" body=\"To report your feedback to GitHub Discussion, you can copy this file as a starting point:\">\n  To report your feedback to GitHub Discussion, you can copy this file as a starting point:\n</FeedbackBlock>\n\n```ts title='lib/github.ts'\nimport { App, Octokit } from 'octokit';\nimport {\n  blockFeedback,\n  BlockFeedback,\n  pageFeedback,\n  type ActionResponse,\n  type PageFeedback,\n} from '@/components/feedback/schema';\n\nexport const repo = 'fumadocs';\nexport const owner = 'fuma-nama';\nexport const DocsCategory = 'Docs Feedback';\n\nlet instance: Octokit | undefined;\n\nasync function getOctokit(): Promise<Octokit> {\n  if (instance) return instance;\n  const appId = process.env.GITHUB_APP_ID;\n  const privateKey = process.env.GITHUB_APP_PRIVATE_KEY;\n\n  if (!appId || !privateKey) {\n    throw new Error('No GitHub keys provided for Github app, docs feedback feature will not work.');\n  }\n\n  const app = new App({\n    appId,\n    privateKey,\n  });\n\n  const { data } = await app.octokit.request('GET /repos/{owner}/{repo}/installation', {\n    owner,\n    repo,\n    headers: {\n      'X-GitHub-Api-Version': '2022-11-28',\n    },\n  });\n\n  instance = await app.getInstallationOctokit(data.id);\n  return instance;\n}\n\ninterface RepositoryInfo {\n  id: string;\n  discussionCategories: {\n    nodes: {\n      id: string;\n      name: string;\n    }[];\n  };\n}\n\nlet cachedDestination: RepositoryInfo | undefined;\nasync function getFeedbackDestination() {\n  if (cachedDestination) return cachedDestination;\n  const octokit = await getOctokit();\n\n  const {\n    repository,\n  }: {\n    repository: RepositoryInfo;\n  } = await octokit.graphql(`\n  query {\n    repository(owner: \"${owner}\", name: \"${repo}\") {\n      id\n      discussionCategories(first: 25) {\n        nodes { id name }\n      }\n    }\n  }\n`);\n\n  return (cachedDestination = repository);\n}\n\nexport async function onPageFeedbackAction(feedback: PageFeedback): Promise<ActionResponse> {\n  'use server';\n  feedback = pageFeedback.parse(feedback);\n  return createDiscussionThread(\n    feedback.url,\n    `[${feedback.opinion}] ${feedback.message}\\n\\n> Forwarded from user feedback.`,\n  );\n}\n\nexport async function onBlockFeedbackAction(feedback: BlockFeedback): Promise<ActionResponse> {\n  'use server';\n  feedback = blockFeedback.parse(feedback);\n  return createDiscussionThread(\n    feedback.url,\n    `> ${feedback.blockBody ?? feedback.blockId}\\n\\n${feedback.message}\\n\\n> Forwarded from user feedback.`,\n  );\n}\n\nasync function createDiscussionThread(pageId: string, body: string) {\n  const octokit = await getOctokit();\n  const destination = await getFeedbackDestination();\n  const category = destination.discussionCategories.nodes.find(\n    (category) => category.name === DocsCategory,\n  );\n\n  if (!category) throw new Error(`Please create a \"${DocsCategory}\" category in GitHub Discussion`);\n\n  const title = `Feedback for ${pageId}`;\n  const {\n    search: {\n      nodes: [discussion],\n    },\n  }: {\n    search: {\n      nodes: { id: string; url: string }[];\n    };\n  } = await octokit.graphql(`\n          query {\n            search(type: DISCUSSION, query: ${JSON.stringify(`${title} in:title repo:${owner}/${repo} author:@me`)}, first: 1) {\n              nodes {\n                ... on Discussion { id, url }\n              }\n            }\n          }`);\n\n  if (discussion) {\n    const result: {\n      addDiscussionComment: {\n        comment: { id: string; url: string };\n      };\n    } = await octokit.graphql(`\n            mutation {\n              addDiscussionComment(input: { body: ${JSON.stringify(body)}, discussionId: \"${discussion.id}\" }) {\n                comment { id, url }\n              }\n            }`);\n\n    return {\n      githubUrl: result.addDiscussionComment.comment.url,\n    };\n  } else {\n    const result: {\n      discussion: { id: string; url: string };\n    } = await octokit.graphql(`\n            mutation {\n              createDiscussion(input: { repositoryId: \"${destination.id}\", categoryId: \"${category.id}\", body: ${JSON.stringify(body)}, title: ${JSON.stringify(title)} }) {\n                discussion { id, url }\n              }\n            }`);\n\n    return {\n      githubUrl: result.discussion.url,\n    };\n  }\n}\n\n```\n\n<FeedbackBlock id=\"6ad4caa13bb55cd9\" body=\"Create your own GitHub App and obtain its app ID and private key.Fill required environment variables.Replace constants like owner, repo, and DocsCategory.Use the onPageFeedbackAction & onBlockFeedbackAction in your feedback components.\">\n  1. Create your own GitHub App and obtain its app ID and private key.\n  2. Fill required environment variables.\n  3. Replace constants like `owner`, `repo`, and `DocsCategory`.\n  4. Use the `onPageFeedbackAction` & `onBlockFeedbackAction` in your feedback components.\n</FeedbackBlock>\n";
